@push('scripts')<script>document.querySelectorAll('[data-editor]').forEach((editor)=>{const input=document.querySelector(`[data-editor-input="${editor.dataset.editor}"]`);const sync=()=>input.value=editor.innerHTML;editor.addEventListener('input',sync);editor.closest('.career-editor-field').querySelectorAll('[data-command]').forEach(button=>button.addEventListener('click',()=>{editor.focus();document.execCommand(button.dataset.command,false,button.dataset.value||null);sync()}));editor.closest('form').addEventListener('submit',sync)});</script>@endpush
